mapper.select:
select t.lock_battery,t.lock_battery lockBattery,t.rel_id,t.rel_id relId,t.ps_state,t.ps_state
psState,t.machine_id,t.machine_id machineId,t.ps_name,t.ps_name psName,t.car_num,t.car_num
carNum,t.ps_id,t.ps_id psId,t.update_time,t.update_time updateTime,t.status_cd,t.status_cd
statusCd,t.community_id,t.community_id communityId,t.lock_state,t.lock_state
lockState,t.image_photo,t.image_photo imagePhoto,t.create_time createTime
from parking_space_machine_rel t
where 1 =1

    and t.lock_battery= #{lockBattery}


    and t.rel_id= #{relId}


    and t.ps_state= #{psState}


    and t.machine_id= #{machineId}


    and t.machine_id in

        #{item}



    and t.ps_name= #{psName}


    and t.car_num= #{carNum}


    and t.ps_id= #{psId}


    and t.update_time= #{updateTime}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.lock_state= #{lockState}


    and t.image_photo= #{imagePhoto}

order by t.create_time desc

    limit #{page}, #{row}

